import { getVersionedNeonServer } from '../react-adapters/utils/react-utils';
/**
 *
 * What are things someone will need to do for the Shadow Root stuff?
 *
 * 1. Create a shadow root on the element
 * 2. Render the react into the shadow root
 *   a. The react component should be wrapped in a div that looks like this
 *       <div neon-react-root dir={document.querySelector('html')?.getAttribute('dir') || undefined}>
 *          <ComponentToRender />
 *       </div>
 *
 * 3. Call applyNeonStylesToShadowDom to the shadow root element and save the returned unloadCallback
 * 4. When the MFE is unloaded, call the unloadCallback.
 */
/**
 * After creating a shadow-dom and rending a react app into it, use this function
 * to ensure that all neon web-components will be supported inside the shadow dom.
 * @param shadowRoot The shadow root to apply neon styles to
 * @returns An unload function. It is good to call this in the mfe unload function.
 */
export function applyNeonStylesToShadowDom(shadowRoot) {
    //Create the link to the neon-styles.css stylesheet and add it to the shadow-dom.
    const neonStylesLink = document.createElement('link');
    neonStylesLink.setAttribute('rel', 'stylesheet');
    neonStylesLink.setAttribute('href', `${getVersionedNeonServer()}/css/neon-styles.css`);
    shadowRoot.appendChild(neonStylesLink);
    //Find all of the neon stylesheets that are already in the document and add them to the shadow-dom.
    const neonStylesheets = document.adoptedStyleSheets.filter((sheet) => {
        if (sheet.neonStyleSheet === true) {
            return true;
        }
        //It turns out that sometimes Safari looses the neonStyleSheet property.
        //webpack.config.js added a fallback for when this happens by adding a fake
        //selector into the stylesheet. If the first selector is the fake selector,
        //then it is assumed to be a neon stylesheet.
        if (sheet.cssRules != null) {
            const rule = sheet.cssRules.item(0);
            if (rule instanceof CSSStyleRule) {
                return rule.selectorText === 'neon-stylesheet-fake-selector';
            }
        }
        return false;
    });
    if (neonStylesheets.length > 0) {
        shadowRoot.adoptedStyleSheets.push(...neonStylesheets);
    }
    //Not all of the neon stylesheets will be present when applyNeonStylesToShadowDom runs.
    //We add in a listener here to listen for any new stylesheets that get added after the fact.
    const neonWebComponentStyleSheetHandler = function (event) {
        const stylesheet = event.detail.stylesheet;
        shadowRoot.adoptedStyleSheets.push(stylesheet);
    };
    document.addEventListener('neonAddStyleSheet', neonWebComponentStyleSheetHandler);
    // This section will mark the root node host which is necessary for some of the neon components to work
    // properly within a shadow-dom
    // We didn't need it for the popover. However, we may need this in the future so we will just leave it
    // commented out.
    // shadowRoot.host.setAttribute('neon-shadow-root-host', '');
    //Returns an unload function that should be called when the shadow-root is going out of scope.
    return function () {
        document.removeEventListener('neonAddStyleSheet', neonWebComponentStyleSheetHandler);
    };
}
